function instructionSections(f,kind){const p=f.participant;const base=[{heading:'Packet and filing location',paragraphs:[`Prepared for ${fullName(p)}. This is a synthetic example, not an actual person or case.`,kind==='arrest'?`This packet concerns an arrest that never became a charge. File only in a court of competent jurisdiction in ${f.court.county} County, where the arrest occurred.`:`This packet concerns Missouri arrest, plea, trial or conviction records under section 610.140. File in ${f.court.county} County, where every listed matter was charged or the finding of guilt entered.`,'Included: CR360 petition; FI-05 confidential filing sheet; the attached continuation when shown; CR370 only because this synthetic fixture says the court expects a proposed judgment; GN10 only when the participant asked for a fee-waiver form; and these instructions.','The clerk assigns the new expungement case number and filing date. The judge or clerk assigns the division. Leave all court findings, hearing information, judgment date and judge signature blank. The participant personally reviews and signs CR360.']},{heading:'Verify records and participant fields before filing',paragraphs:[kind==='arrest'?'Obtain the arrest report and a fingerprint-based Missouri State Highway Patrol record. Confirm the arrest date, arrest county, arresting agency, alleged offense, that no charge was ever filed, and that no charge or guilty finding occurred during the eighteen-month period.':'Obtain a Case.net printout, certified docket sheet and judgment for every case; any probation or parole discharge; clerk payment histories showing all fines, costs and restitution satisfied; and a fingerprint-based Missouri State Highway Patrol record. Compare every case number, court, charge date, county or municipality, offense description, completion date, OCN and prior-expungement answer.',`Confirm the participant identity and contact data: full legal name, date of birth, sex selection, race and ethnicity selection, current address, driver-license number/state/expiration, phone, email and full Social Security number for confidential FI-05. FI-05 is confidential and must go through the clerk’s confidential filing channel.`,'Confirm every agency defendant against the records. An expungement order does not affect an entity that is not named. Do not invent an agency or address. Extra records and agencies are carried on the continuation.','Review CR360 paragraphs 1 through 7 and the prior-expungement election. The official form prints sworn factual and legal statements. LegalEase has not chosen the public-safety or interests-of-justice conclusions. Sign only if every printed statement and attachment is true.']},{heading:'Fees, signatures and clerk handback',paragraphs:['Ask the filing clerk for the current county-variable filing fee, accepted payment method, copy count, and whether the court expects CR370. The former $250 surcharge was repealed and is not quoted here.','If requesting a waiver, review GN10’s income, expenses, assets and debts; supply the Respondent’s Address/Telephone caption field as the clerk directs for multiple defendants; then personally date and sign the penalty-of-perjury statement. The held SJRC (07-15) GN10 is one page and carries no page-two court order. No income answer, signature or court decision is inferred.','The participant does not serve the prosecutor. The clerk gives statutory notice. A prosecutor may object within thirty days after receiving service; the court may set a hearing. Obtain the actual hearing notice from the court rather than writing a date or claiming notice occurred.','After a signed judgment, obtain a filed copy and ask which named agencies received it. CR370 in this packet is an unsigned proposal and is never proof that relief was granted. Missouri relief closes records under section 610.120; it does not destroy them.']},{heading:'Stop and get legal or clerk help',paragraphs:[...(kind==='arrest'?['Do not file this route if a charge was opened from the arrest, fewer than eighteen months have passed, or the participant was charged or found guilty of a misdemeanor or felony during that period.','Review the separate section 610.122 route first if the arrest involved false information or a qualifying chapter 303/moving-violation disposition, because that route may provide destruction rather than closure.','CR360 prints conviction-oriented sentences even on this arrest-only route. The attached section 610.140.7 continuation preserves the official form and supplies arrest-only facts. Before signing or filing, confirm with the clerk or counsel that CR360 plus this continuation is accepted and that case type X5 is correct. The repository’s held legal record marks both as unresolved release questions.','A second arrest during the eighteen-month period, and whether an arrest-only expungement counts against lifetime offense caps, remain questions for counsel. Stop rather than guessing.']:['Stop if any listed matter is in another filing county, if the waiting period measured from completion has not run, if obligations remain unpaid or disputed, if charges are pending, or if the clean-period condition is not met.','Stop for counsel if any offense may be a class A or dangerous felony, a registration offense, a felony involving death, felony assault, domestic assault, felony kidnapping, an excluded sex offense, an intoxication-related traffic/boating/aircraft offense, an equivalent ordinance violation, a commercial-driver motor-vehicle offense, or an unlawful-use-of-weapons offense.','Stop if prior expungements may exhaust the lifetime cap, crimes may or may not be part of one course of conduct, the prosecutor or a victim contests relief, or a denial/appeal requires litigation.']), 'These packet pages prepare forms; they do not decide eligibility, make sworn statements for the participant, or provide a court ruling.']}];return base;}
export async function buildInstructions(f,kind){const build=textPageBuilder(kind==='arrest'?'Missouri arrest-only expungement filing guide':'Missouri conviction expungement filing guide',instructionSections(f,kind));return {...await build(),sections:instructionSections(f,kind)};}
function mapRows(fixture,component,result){const writes=(result.mapped??[]).map((w,i)=>({fieldId:`${fixture}/${component}/${w.field}/${i}`,field:w.field,name:w.field,label:w.label,printedLabel:w.printedLabel,documentId:w.document||`${fixture}/${component}`,fixture,page:w.page,rect:w.rect,value:w.value,factId:`${fixture}.${w.factId}`,decision:'write',isSelectionControl:w.isSelectionControl}));const blanks=(result.blanks??[]).map(x=>({...x,fieldId:x.fieldId||`${fixture}/${component}/${x.field}`,documentId:x.document?`${fixture}/${x.document}`:`${fixture}/${component}`,fixture}));return {writes,blanks};}
function markdownInstructions(sections){return sections.map(s=>`## ${s.heading}\n\n${s.paragraphs.join('\n\n')}`).join('\n\n')+'\n';}
function validatePacketText(bytes,expected,forbidden){const tmp=`/tmp/mo-packet-${process.pid}-${Math.random().toString(16).slice(2)}.pdf`,txt=tmp+'.txt';fs.writeFileSync(tmp,bytes);const p=spawnSync('pdftotext',['-layout',tmp,txt],{encoding:'utf8'});if(p.status!==0)throw Error(`PDFTOTEXT_FAILED:${p.stderr}`);const out=fs.readFileSync(txt,'utf8').replace(/\s+/g,' ');for(const x of expected)if(!out.includes(x.replace(/\s+/g,' ')))throw Error(`OUTPUT_TEXT_MISSING:${x}`);for(const x of forbidden)if(out.includes(x))throw Error(`DELIVERED_INTERNAL_TEXT:${x}`);return {characters:out.replace(/\s/g,'').length};}
async function assemble(components){const doc=stampDeterministic(await PDFDocument.create()),coverage=[];let first=1;for(const c of components){const d=await PDFDocument.load(c.bytes,{updateMetadata:false});for(const p of await doc.copyPages(d,d.getPageIndices()))doc.addPage(p);coverage.push({documentId:c.id,role:c.role,firstPage:first,pageCount:c.pages,lastPage:first+c.pages-1,sha256:hash(c.bytes)});first+=c.pages;}return {bytes:await doc.save({useObjectStreams:false}),pages:doc.getPageCount(),coverage};}
export async function buildPacket(input,kind,fixture,root=ROOT){const f=importFacts(input,kind),parts=[];const cr=await buildCR360(f,kind,fixture,root);parts.push({id:'CR360',role:'primary_filing',...cr});if(kind==='arrest'||f.cases.length>9||f.respondents.some(x=>x.kind==='other'))parts.push({id:'continuation',role:'continuation',...await buildContinuation(f,kind)});const fi=await buildFI05(f,fixture,root);parts.push({id:'FI-05',role:'cover_sheet',...fi});if(f.proposedOrderRequested)parts.push({id:'CR370',role:'proposed_order',...await buildCR370(f,kind,fixture,root)});if(f.feeWaiverRequested)parts.push({id:'GN10',role:'fee_waiver',...await buildGN10(f,fixture,root)});const ins=await buildInstructions(f,kind);parts.push({id:'instructions',role:'instructions',...ins});const packet=await assemble(parts);const expected=[fullName(f.participant),kind==='arrest'?'arrest-only expungement filing guide':'conviction expungement filing guide','Expungement of Records (610.140 RSMo)'];const proof=validatePacketText(packet.bytes,expected,[ROUTES[kind].routeKey,'obligation:','SOURCE_BLOCKED','internal route']);return {f,parts,packet:{...packet,proof},map:parts.flatMap(c=>{const r=mapRows(fixture,c.id,c);return [...r.writes,...r.blanks]}),instructions:ins};}
function sourceReceipt(route,root){return {schemaVersion:'rcap-source-receipt/v1',familyId:route.familyId,allSourcesExact:true,documents:Object.entries(SOURCES).map(([formNumber,s])=>({formNumber:formNumber==='FI05'?'FI-05':formNumber,sourceId:s.sourceId,path:s.path,sha256:s.sha256,byteLength:fs.statSync(path.join(root,s.path)).size,pages:s.pages,mediaType:s.mediaType,revision:s.revision,sha256Exact:true})),scope:'Exact held source identities. GN10 is a one-page DOCX; its generated PDF component is a source-derived print rendering guarded by the exact DOCX hash, not a substituted PDF.'};}
function publishDirectory(temp,target){
 fs.mkdirSync(target,{recursive:true});
 const walk=dir=>fs.readdirSync(dir,{withFileTypes:true}).flatMap(entry=>entry.isDirectory()?walk(path.join(dir,entry.name)):[path.join(dir,entry.name)]);
 for(const source of walk(temp)){const rel=path.relative(temp,source),dest=path.join(target,rel),stage=`${dest}.new-${process.pid}`;fs.mkdirSync(path.dirname(dest),{recursive:true});fs.copyFileSync(source,stage);fs.renameSync(stage,dest);}
 fs.rmSync(temp,{recursive:true});
}
